function Add-Log([string]$Step, [int]$Code, [double]$Sec, [string]$Err) {
  $CmdLog.Add([pscustomobject]@{ step = $Step; ok = ($Code -eq 0); seconds = [math]::Round($Sec, 1); error = $Err })
}

# Runs the CLI only for read commands on the allowed list.
function Invoke-AzRaw([string[]]$AzArgs) {
  $path = @(); foreach ($t in $AzArgs) { if ($t.StartsWith('-')) { break }; $path += $t }
  $cmd = $path -join ' '
  if ($AllowedCmds -notcontains $cmd) { throw "Command blocked (not on the read list): az $cmd" }
  if ($cmd -eq 'rest') {
    $j = ' ' + ($AzArgs -join ' ') + ' '
    $okPerm = $j -match ' --url https://management\.azure\.com/subscriptions/[0-9a-fA-F-]{36}/providers/Microsoft\.Authorization/permissions\?api-version=[0-9-]+ '
    $okPric = $j -match ' --url https://management\.azure\.com/subscriptions/[0-9a-fA-F-]{36}/resourceGroups/[^/\s]+/providers/Microsoft\.HybridCompute/machines/[^/\s]+/providers/Microsoft\.Security/pricings/VirtualMachines\?api-version=2024-01-01 '
    if ($j -notmatch ' --method get ' -or -not ($okPerm -or $okPric)) {
      throw 'Command blocked: az rest is allowed only as GET on the effective permissions and per Arc machine Defender plan APIs.' }
  }
  $prev = $ErrorActionPreference; $ErrorActionPreference = 'Continue'
  try { $out = & az @AzArgs --only-show-errors -o json 2>&1; $code = $LASTEXITCODE }
  finally { $ErrorActionPreference = $prev }
  $err = @($out | Where-Object { $_ -is [System.Management.Automation.ErrorRecord] } | ForEach-Object { $_.ToString() }) -join ' '
  $txt = @($out | Where-Object { $_ -isnot [System.Management.Automation.ErrorRecord] }) -join [Environment]::NewLine
  return [pscustomobject]@{ Code = $code; Text = $txt; Err = $err }
}

# Paginated Azure Resource Graph query; stores the result in $DS[$Name] ($null = failure).
function Invoke-Arg([string]$Name, [string]$Query) {
  Write-Step "Collecting $Name (Resource Graph)"
  $Query = ($Query -replace '\s*\r?\n\s*', ' ').Trim()
  $all = New-Object System.Collections.Generic.List[object]
  $skip = $null; $pages = 0; $ok = $true; $errTxt = ''
  $sw = [Diagnostics.Stopwatch]::StartNew()
  do {
    $a = @('graph', 'query', '-q', $Query, '--first', '1000') + $ArgScope
    if ($skip) { $a += @('--skip-token', $skip) }
    $r = Invoke-AzRaw $a
    if ($r.Code -ne 0) { $ok = $false; $errTxt = $r.Err; break }
    $resp = $r.Text | ConvertFrom-Json
    foreach ($row in @($resp.data)) { if ($null -ne $row) { $all.Add($row) } }
    $skip = $null
    if ($resp.PSObject.Properties['skip_token'] -and $resp.skip_token) { $skip = $resp.skip_token }
    $pages++
  } while ($skip -and $pages -lt 500)
  $sw.Stop()
  $code = 0; if (-not $ok) { $code = 1 }
  Add-Log $Name $code $sw.Elapsed.TotalSeconds $errTxt
  if (-not $ok) { Write-Warning "[$Name] failed: $errTxt"; $DS[$Name] = $null; return }
  $arr = $all.ToArray()
  Save-Json $Name $arr
  $DS[$Name] = $arr
}

# One call per subscription; aggregates the rows with subscriptionId/subscriptionName.
function Invoke-PerSub([string]$Name, [scriptblock]$ArgsFor) {
  Write-Step "Collecting $Name ($($Subs.Count) subscription(s))"
  $all = New-Object System.Collections.Generic.List[object]
  foreach ($s in $Subs) {
    $a = @(& $ArgsFor $s.subscriptionId)
    $sw = [Diagnostics.Stopwatch]::StartNew(); $r = Invoke-AzRaw $a; $sw.Stop()
    Add-Log ($Name + '/' + $s.name) $r.Code $sw.Elapsed.TotalSeconds $r.Err
    if ($r.Code -ne 0) { Write-Warning "[$Name/$($s.name)] failed: $($r.Err)"; continue }
    $obj = $null
    if ($r.Text -and $r.Text.Trim()) { $obj = $r.Text | ConvertFrom-Json }
    if ($null -ne $obj -and $obj -isnot [array] -and $obj.PSObject.Properties['value']) { $obj = $obj.value }
    foreach ($row in @($obj)) {
      if ($null -eq $row) { continue }
      $row | Add-Member -NotePropertyName subscriptionId -NotePropertyValue $s.subscriptionId -Force
      $row | Add-Member -NotePropertyName subscriptionName -NotePropertyValue $s.name -Force
      $all.Add($row)
    }
  }
  $arr = $all.ToArray()
  Save-Json $Name $arr
  $DS[$Name] = $arr
}

