$SubIds = @()
foreach ($s in @($Subscriptions | Where-Object { $_ })) {
  if ($s -match '^[0-9a-fA-F-]{36}$') { $SubIds += $s; continue }
  $r = Invoke-AzRaw @('account', 'show', '--subscription', $s)
  if ($r.Code -eq 0) { $SubIds += ($r.Text | ConvertFrom-Json).id } else { Write-Warning "Subscription not found: $s" }
}
if ($ManagementGroup) { $ArgScope = @('--management-groups', $ManagementGroup) }
else {
  $SubIds = @($SubIds | Where-Object { $_ })
  if ($SubIds.Count -eq 0 -and $Account.id) { $SubIds = @([string]$Account.id) }
  if ($SubIds.Count -eq 0) {
    # No default subscription in the CLI: uses the enabled subscriptions of the account.
    $lr = Invoke-AzRaw @('account', 'list', '--query', '[].{id:id,name:name,state:state,tenantId:tenantId}')
    if ($lr.Code -eq 0) { $SubIds = @(@($lr.Text | ConvertFrom-Json) | Where-Object { $_.state -eq 'Enabled' -and (-not $Account.tenantId -or $_.tenantId -eq $Account.tenantId) } | ForEach-Object { [string]$_.id }) }
  }
  if ($SubIds.Count -eq 0) { throw 'No subscription set. Run az account set --subscription <ID> or specify -Subscriptions <ID1>,<ID2>.' }
  $ArgScope = @('--subscriptions') + $SubIds
}
