function Test-PermAction($Entries, [string]$Action) {
  foreach ($e in @($Entries)) {
    $allow = $false
    foreach ($a in @($e.actions)) { if ($a -and ($Action -like [string]$a)) { $allow = $true; break } }
    if (-not $allow) { continue }
    $deny = $false
    foreach ($n in @($e.notActions)) { if ($n -and ($Action -like [string]$n)) { $deny = $true; break } }
    if (-not $deny) { return $true }
  }
  return $false
}
