    Add-Log ('pricingRes/' + $x.name) $r.Code $sw.Elapsed.TotalSeconds $r.Err
    $row = [ordered]@{ subscriptionId = $x.subscriptionId; resourceGroup = $x.resourceGroup; machine = $x.name; tier = ''; subPlan = ''; inherited = ''; inheritedFrom = ''; extensions = ''; error = '' }
