      $row.extensions = (@($p.extensions | Where-Object { [string]$_.isEnabled -eq 'True' } | ForEach-Object { $_.name }) -join ', ')
    } else { $row.error = ([string]$r.Err).Substring(0, [math]::Min(200, ([string]$r.Err).Length)) }
    $all.Add([pscustomobject]$row)
