function Get-AgentRelease([int]$Minor) {
  if ($AgentReleases.ContainsKey($Minor)) { return [pscustomobject]@{ date = [datetime]($AgentReleases[$Minor] + '-01'); estimated = $false } }
  if ($Minor -lt 0) { return [pscustomobject]@{ date = [datetime]'2000-01-01'; estimated = $true } }
  return [pscustomobject]@{ date = ([datetime]($AgentReleases[$AgentLatest] + '-01')).AddMonths($Minor - $AgentLatest); estimated = $true }
}
