    $k = Get-MachineKey $x.resourceGroup $x.name
    $vm = @($pr | Where-Object { $_.subscriptionId -eq $x.subscriptionId -and $_.name -eq 'VirtualMachines' }) | Select-Object -First 1
    $def = 'Free'; if ($vm -and $vm.pricingTier -eq 'Standard') { $def = 'P1'; if ([string]$vm.subPlan -match 'P2') { $def = 'P2' } }
    $vr = @($DS['pricingRes'] | Where-Object { $_ -and -not $_.error -and (Get-MachineKey $_.resourceGroup $_.machine) -eq $k }) | Select-Object -First 1
    if ($vr) { $def = 'Free'; if ($vr.tier -eq 'Standard') { $def = 'P1'; if ([string]$vr.subPlan -match 'P2') { $def = 'P2' } } }
    $isWin = ([string]$x.osType -eq 'windows')
    $sa = $isWin -and (([string]$x.saCustomer -eq 'true') -or ([string]$x.wsMgmt -match 'WindowsServerAzureArcMgmt' -and [string]$x.wsMgmt -match 'Enabled'))
    $payg = $isWin -and ([string]$x.wsPayg -eq 'Enabled')
    $esu = ([string]$x.esu -eq 'Assigned')
    $ben = @(); if ($def -eq 'P2') { $ben += 'Defender P2' }; if ($sa) { $ben += 'Attested SA' }; if ($payg) { $ben += 'WS PAYG' }; if ($esu) { $ben += 'ESU' }
    $covered = ($ben.Count -gt 0)
    $aum = (([string]$x.patchAssessment -eq 'AutomaticByPlatform') -or ([string]$x.linuxPatchAssessment -eq 'AutomaticByPlatform'))
    $gcn = 0; if ($gcIx.ContainsKey($k)) { $gcn = $gcIx[$k] }
    $hasCt = $ct.ContainsKey($k)
    $cDef = 0; if ($def -eq 'P1') { $cDef = $P_DEF1 } elseif ($def -eq 'P2') { $cDef = $P_DEF2 }
    $cAum = 0; if ($aum -and -not $covered) { $cAum = $P_AUM }
    $cGc = 0; if (($gcn -gt 0 -or $hasCt) -and -not $covered) { $cGc = $P_GC }
    $cPay = 0; if ($payg -and $x.cores) { $cPay = [math]::Round(([double]$x.cores) * $P_WSPAYG, 2) }
    $sub = $cDef + $cAum + $cGc + $cPay
    $tot += $sub
    if ($covered) { $nBen++ }
    $hasAma = $ama.ContainsKey($k); if ($hasAma) { $nAma++ }
    $opp = 0; if ($isWin -and -not $covered -and ($cAum + $cGc) -gt 0) { $opp = $cAum + $cGc; $save += $opp; $nSave++ }
    $var = @(); if ($hasAma) { $var += 'Log Analytics (US$ 2,76/GB)' }
    $rows.Add([pscustomobject]@{ name = $x.name; resourceGroup = $x.resourceGroup; subscriptionId = $x.subscriptionId; os = $x.osType; defender = $def; beneficios = ($ben -join ', '); updateManager = $cAum; machineConfigChangeTracking = $cGc; defenderUsd = $cDef; wsPaygUsd = $cPay; cores = $x.cores; estimativaUsdMes = $sub; economiaSeSaAtestado = $opp; variaveis = ($var -join ', '); atribuicoesGc = $gcn })
  }
  $arr = $rows.ToArray()
  $msg = "List price estimate: US$ {0:N2}/month for {1} connected server(s) (Defender, Update Manager, Machine Configuration/Change Tracking, and WS PAYG). {2} with benefit (Defender P2, attested SA, WS PAYG, or ESU). {3} with AMA: Log Analytics cost per GB not estimated." -f $tot, $m.Count, $nBen, $nAma
  if ($nSave) { Set-Result 'WARN' $arr.Count ($msg + (" {0} Windows Server paying for Update Manager/Machine Configuration without benefit: up to US$ {1:N2}/month avoidable if they have Software Assurance (attest in Azure Arc > Azure Benefits - Windows Server)." -f $nSave, $save)) $arr }
  else { Set-Result 'INFO' $arr.Count $msg $arr }
}
$Eval['CHK-43'] = {
  $d = @($DS['diag'])
  $rows = @(foreach ($s in $Subs) { if (-not @($d | Where-Object { $_.subscriptionId -eq $s.subscriptionId -and $_.workspaceId }).Count) { [pscustomobject]@{ subscription = $s.name; subscriptionId = $s.subscriptionId } } })
  if ($rows.Count) { Set-Result 'FAIL' $rows.Count "$($rows.Count) subscription(s) without Activity Log export to Log Analytics (native retention of 90 days)." $rows }
  else { Set-Result 'PASS' 0 'Activity Log exported to Log Analytics in all subscriptions.' }
}
$Eval['CHK-44'] = {
  $ev = @($DS['activity'] | Where-Object { @('Started', 'Accepted') -notcontains $_.status })
  $cls = @(foreach ($x in $ev) {
      $op = [string]$x.op; $c = $null
      if ($op -match 'runCommands/write') { $c = 'Run Command' }
      elseif ($op -match 'extensions/write') { $c = 'Extension installed/changed' }
      elseif ($op -match 'extensions/delete') { $c = 'Extension removed' }
      elseif ($op -match 'machines/delete') { $c = 'Machine removed' }
      elseif ($op -match 'licenses/write|licenseProfiles/write') { $c = 'License/ESU' }
      if ($c) { [pscustomobject]@{ category = $c; time = $x.time; caller = $x.caller; status = $x.status; resourceId = $x.resourceId; correlationId = $x.correlationId } } })
  $sum = ($cls | Group-Object category | ForEach-Object { "$($_.Name): $($_.Count)" }) -join ', '
  $risk = @($cls | Where-Object { $_.category -eq 'Run Command' -or $_.category -match 'removed' }).Count
  if (-not $cls.Count) { Set-Result 'PASS' 0 "No sensitive operations in $ActivityDays day(s) ($($ev.Count) HybridCompute provider events)." }
  elseif ($risk) { Set-Result 'WARN' $cls.Count "Sensitive operations in $ActivityDays day(s) - $sum. Review author and justification." $cls }
  else { Set-Result 'INFO' $cls.Count "Operations in $ActivityDays day(s) - $sum." $cls }
}
$Eval['CHK-45'] = {
  $all = @($DS['related'] | Where-Object { $_.type -eq 'microsoft.operationalinsights/workspaces' })
  $ids = Get-ArcWorkspaceIds
  $w = @($all | Where-Object { $ids.ContainsKey(([string]$_.id).ToLower()) })
  $out = $all.Count - $w.Count
  if (-not $w.Count) { Set-Result 'N/A' 0 ("No workspace receives data from the Arc machines through a DCR (see DCR association and telemetry). Workspaces outside the Arc scope (ignored): {0}." -f $out); return }
  $rows = @($w | Where-Object { [int]$_.retentionDays -lt 90 } | Select-Object name, resourceGroup, retentionDays)
  if ($rows.Count) { Set-Result 'WARN' $rows.Count ("{0} of {1} workspace(s) receiving data from the Arc machines with retention below 90 days. Outside the Arc scope (ignored): {2}." -f $rows.Count, $w.Count, $out) $rows }
  else { Set-Result 'PASS' 0 ("The {0} workspace(s) receiving data from the Arc machines retain 90 days or more. Outside the Arc scope (ignored): {1}." -f $w.Count, $out) }
}

Write-Step 'Evaluating checks'
foreach ($c in $Catalog) {
  if ($Checks -notcontains $c.id) { continue }
  $script:cur = [ordered]@{ id = $c.id; domain = $c.domain; title = $c.title; severity = $c.sev; type = $c.type; status = 'MANUAL'; found = 0; detail = ''; file = '' }
  if ($c.type -eq 'manual') { $cur.detail = 'Documentary control: validate with the customer and record the evidence.' }
  else {
    $missing = @(@($c.ds) | Where-Object { $_ -and ($null -eq $DS[$_]) })
    if ($missing.Count) { $cur.status = 'ERRO'; $cur.detail = 'Collection failed: ' + ($missing -join ', ') + ' (see commands in results.json and run.log).' }
    elseif (-not $Eval.ContainsKey($c.id)) { $cur.status = 'INFO'; $cur.detail = 'No automatic assessment.' }
    else { try { & $Eval[$c.id] } catch { $cur.status = 'ERRO'; $cur.detail = 'Assessment error (line ' + $_.InvocationInfo.ScriptLineNumber + '): ' + $_.Exception.Message } }
    try { Update-PermGap @($c.ds) } catch { }
  }
  $Results.Add([pscustomobject]$cur)
  Write-Host ('  {0,-7} {1,-6} {2}' -f $cur.id, $cur.status, $cur.title)
}

# ===================== Saidas =====================
$Dur = [math]::Round([double]$Clock.Elapsed.TotalSeconds, 1)
$Counts = @{}; foreach ($g in @($Results | Group-Object status)) { $Counts[[string]$g.Name] = [int]$g.Count }
$CountTxt = (@($Results | Group-Object status | ForEach-Object { '{0} {1}' -f $_.Name, $_.Count })) -join ' | '
function ConvertTo-MdCell([string]$s) { return (([string]$s) -replace '\|', '/' -replace '\r?\n', ' ') }
$sevRank = @{ 'High' = 0; 'Media' = 1; 'Medium' = 1; 'Low' = 2 }
$L = New-Object System.Collections.Generic.List[string]
$L.Add('# Azure Arc - initial security collection')
$L.Add('')
$L.Add("- Versao: $ScriptVersion | Inicio: $($Start.ToString('yyyy-MM-dd HH:mm:ss')) | Duration: $Dur s")
$L.Add("- Account: $($Account.user.name) | Tenant: $($Account.tenantId)")
$scopeTxt = 'Subscriptions: ' + (($Subs | ForEach-Object { $_.name }) -join ', ')
if ($ManagementGroup) { $scopeTxt = "Management group: $ManagementGroup ($($Subs.Count) subscriptions)" }
$L.Add("- Scope: $scopeTxt | RG: $(if ($ResourceGroup) { $ResourceGroup } else { 'all' }) | Machine: $(if ($MachineName) { $MachineName } else { 'all' })")
$L.Add('- Result: ' + $CountTxt)
$L.Add('')
$L.Add('## Priorities (FAIL and WARN)')
$L.Add('')
$L.Add('| Status | Sev. | ID | Check | Achados | Detail |')
$L.Add('|---|---|---|---|---:|---|')
$prio = @(foreach ($x in $Results) {
    if (@('FAIL', 'WARN') -notcontains [string]$x.status) { continue }
    $k1 = 1; if ([string]$x.status -eq 'FAIL') { $k1 = 0 }
    $k2 = 1; $sv = [string]$x.severity; if ($sv -eq 'High') { $k2 = 0 } elseif ($sv -eq 'Low') { $k2 = 2 }
    [pscustomobject]@{ k1 = [int]$k1; k2 = [int]$k2; id = [string]$x.id; item = $x } }) | Sort-Object k1, k2, id | ForEach-Object { $_.item }
foreach ($x in $prio) { $L.Add("| $($x.status) | $($x.severity) | $($x.id) | $(ConvertTo-MdCell $x.title) | $($x.found) | $(ConvertTo-MdCell $x.detail) |") }
if (-not @($prio).Count) { $L.Add('| - | - | - | No FAIL/WARN | 0 | - |') }
foreach ($d in ($Results | Group-Object domain)) {
  $L.Add(''); $L.Add("## $($d.Name)"); $L.Add('')
  $L.Add('| ID | Check | Sev. | Status | Achados | Detail | Evidence |'); $L.Add('|---|---|---|---|---:|---|---|')
  foreach ($x in $d.Group) { $L.Add("| $($x.id) | $(ConvertTo-MdCell $x.title) | $($x.severity) | $($x.status) | $($x.found) | $(ConvertTo-MdCell $x.detail) | $($x.file) |") }
}
$L.Add(''); $L.Add('## Collection account permissions'); $L.Add('')
$L.Add('Account: ' + [string]$Account.user.name + ' (' + $acctType + '). Source: effective permissions per subscription (includes groups and management group inheritance).'); $L.Add('')
$L.Add('| Subscription | Area | Obrigatoria | Status | Missing actions |'); $L.Add('|---|---|---|---|---|')
foreach ($x in $PermArr) { $L.Add('| ' + (ConvertTo-MdCell $x.subscription) + ' | ' + $x.area + ' | ' + $x.obrigatoria + ' | ' + $x.status + ' | ' + (ConvertTo-MdCell $x.acoesFaltantes) + ' |') }
$L.Add(''); $L.Add('## Chamadas a CLI'); $L.Add('')
$L.Add('| Step | OK | Seconds | Error |'); $L.Add('|---|---|---:|---|')
foreach ($c in $CmdLog) { $L.Add("| $($c.step) | $($c.ok) | $($c.seconds) | $(ConvertTo-MdCell $c.error) |") }
try { Save-Text (Join-Path $RunDir 'summary.md') ($L -join [Environment]::NewLine) } catch { Write-Warning ('Failed to write summary.md (line {0}): {1}' -f $_.InvocationInfo.ScriptLineNumber, $_.Exception.Message) }

function Add-Prop($Obj, [string]$Name, [scriptblock]$Value) {
  $v = $null
  try { $v = & $Value } catch { Write-Warning ('Field ' + $Name + ' ignored (row ' + $_.InvocationInfo.ScriptLineNumber + '): ' + $_.Exception.Message) }
  $Obj | Add-Member -NotePropertyName $Name -NotePropertyValue $v -Force
}
$scopeObj = New-Object psobject
Add-Prop $scopeObj 'managementGroup' { $ManagementGroup }
Add-Prop $scopeObj 'subscriptions' { , @($Subs | ForEach-Object { $_ }) }
Add-Prop $scopeObj 'resourceGroup' { $ResourceGroup }
Add-Prop $scopeObj 'machine' { $MachineName }
Add-Prop $scopeObj 'activityDays' { $ActivityDays }
Add-Prop $scopeObj 'requiredTags' { , @($RequiredTags | Where-Object { $_ }) }
$meta = New-Object psobject
Add-Prop $meta 'tool' { 'arc-posture-review' }
Add-Prop $meta 'version' { $ScriptVersion }
Add-Prop $meta 'schemaVersion' { 2 }
Add-Prop $meta 'startedAt' { Get-Date -Date $Start -Format 'o' }
Add-Prop $meta 'durationSec' { $Dur }
Add-Prop $meta 'account' { [string]$Account.user.name }
Add-Prop $meta 'accountType' { $acctType }
Add-Prop $meta 'tenantId' { [string]$Account.tenantId }
Add-Prop $meta 'scope' { $scopeObj }
Add-Prop $meta 'counts' { $Counts }
Add-Prop $meta 'permissions' { , $PermArr }
Add-Prop $meta 'results' { , $Results.ToArray() }
Add-Prop $meta 'commands' { , $CmdLog.ToArray() }
try { Save-Text (Join-Path $RunDir 'results.json') (ConvertTo-Json -InputObject $meta -Depth 8) } catch { Write-Warning ('Failed to write results.json (line {0}): {1}' -f $_.InvocationInfo.ScriptLineNumber, $_.Exception.Message) }

try { Stop-Transcript | Out-Null } catch { }
$files = @(Get-ChildItem -Path $RunDir -Recurse -File | Where-Object { $_.Name -ne 'manifest.json' })
$base = (Resolve-Path $RunDir).Path
$manFiles = New-Object System.Collections.Generic.List[object]
foreach ($f in $files) {
  try {
    $rel = (($f.FullName -replace ('^' + [regex]::Escape($base)), '') -replace '\\', '/') -replace '^/+', ''
    $manFiles.Add([pscustomobject]@{ path = $rel; size = $f.Length; sha256 = (Get-FileHash -Path $f.FullName -Algorithm SHA256).Hash })
  } catch { Write-Warning ('Manifest: ' + $f.Name + ' skipped: ' + $_.Exception.Message) }
}
$man = New-Object psobject
Add-Prop $man 'generatedAt' { Get-Date -Format 'o' }
Add-Prop $man 'version' { $ScriptVersion }
Add-Prop $man 'tool' { 'arc-posture-review' }
Add-Prop $man 'schemaVersion' { 2 }
Add-Prop $man 'files' { , $manFiles.ToArray() }
try { Save-Text (Join-Path $RunDir 'manifest.json') (ConvertTo-Json -InputObject $man -Depth 5) } catch { Write-Warning ('Failed to write manifest.json (line {0}): {1}' -f $_.InvocationInfo.ScriptLineNumber, $_.Exception.Message) }

$Zip = $RunDir + '.zip'
try {
  Compress-Archive -Path (Join-Path $RunDir '*') -DestinationPath $Zip -Force; Write-Step "Package: $Zip"
  try { $zh = (Get-FileHash -Path $Zip -Algorithm SHA256).Hash; Write-Step "Package SHA-256: $zh (verify in step 3 of the checklist)"; Save-Text ($Zip + '.sha256') ($zh + '  ' + (Split-Path $Zip -Leaf)) } catch { }
}
catch { Write-Warning "Could not compress ($($_.Exception.Message)). Compress the folder $RunDir manually." }
Write-Step ("Completed in $Dur s. $CountTxt")
Write-Step 'Upload the .zip on the checklist Results tab.'
